styles:
.reader-quote {
  font-style: normal;
  color: #58a6ff;
  font-family: 'Courier New', 'Consolas', monospace;
  background: rgba(88, 166, 255, 0.06);
  border-left: 2px solid #58a6ff;
  padding-left: 6px;
}
.reader-ellipsis {
  letter-spacing: 6px;
  color: #4a8fd4;
}
.reader-dash {
  letter-spacing: 4px;
  color: #3a7ab8;
}
.reader-speak {
  color: #7ee787;
  font-weight: 600;
  font-family: 'Courier New', monospace;
  border-bottom: 1px dashed #7ee787;
  padding-bottom: 1px;
}
